cd /challenge/inhere; python3 - <<'EOF'
import os
for area in sorted(os.listdir('.')):
    recdir = os.path.join(area, '.records')
    for item in sorted(os.listdir(recdir)):
        p = os.path.join(recdir, item)
        data = open(p,'rb').read()
        unit = f"record {area[4:]}-{item[4:]}\n".encode()
        full = (unit * (len(data)//len(unit)+1))[:len(data)]
        if data != full:
            print("ANOMALY:", p, "size", len(data), "mode", oct(os.stat(p).st_mode & 0o777))
            # show first divergence
            for i,(a,b) in enumerate(zip(data,full)):
                if a!=b:
                    print("  first diff at byte", i, repr(data[max(0,i-20):i+60]))
                    break
            else:
                print("  (prefix matches)")
EOF

